        });

        btnClear.addActionListener(e -> loadProfileData());
        btnSave.addActionListener(e -> saveProfile());

        btnBack.addActionListener(e -> {
            dispose();
            new TechOfficerDashboard(techOffId).setVisible(true);
        });

        setVisible(true);
    }

    //load profile data
    private void loadProfileData() {
        try {
            Connection con = DBConnection.getConnection();

            //Load main details
            String sql1 = "SELECT * FROM tech_officer WHERE Techoff_id=?";
            PreparedStatement pst1 = con.prepareStatement(sql1);
            pst1.setString(1, techOffId);

            ResultSet rs1 = pst1.executeQuery();

            if (rs1.next()) {
                tToId.setText(rs1.getString("Techoff_id"));
                tName.setText(rs1.getString("Name"));
                tEmail.setText(rs1.getString("Email"));
                tNic.setText(rs1.getString("Nic"));
                tDob.setText(rs1.getString("Dob"));


                String address = rs1.getString("No") + ", "
                        + rs1.getString("Street") + ", "
                        + rs1.getString("City");

                tAddress.setText(address);
            }



            //load user table
            String sql2 = "SELECT password, profile_pic FROM user WHERE user_id=?";
            PreparedStatement pst2 = con.prepareStatement(sql2);
            pst2.setString(1, techOffId);

            ResultSet rs2 = pst2.executeQuery();

            if (rs2.next()) {
                fPassword.setText(rs2.getString("password"));
                imagePath = rs2.getString("profile_pic");

                if (imagePath != null && !imagePath.isEmpty()) {
                    setProfileImage(imagePath);
                }
            }

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    //display image
    private void setProfileImage(String path) {
        try {
            // Handle relative paths
            if (path.startsWith("src/")) {
                path = System.getProperty("user.dir") + "/" + path;
            }

            File file = new File(path);

            if (!file.exists()) return;

            ImageIcon icon = new ImageIcon(path);

            Image img = icon.getImage().getScaledInstance(
                    120, 120, Image.SCALE_SMOOTH
            );

            pplabel.setIcon(new ImageIcon(img));

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    //save profile
    private void saveProfile() {
        try {
            Connection con = DBConnection.getConnection();

            String name = tName.getText();
            String password = new String(fPassword.getPassword());

            // Split address back into parts
            String[] parts = tAddress.getText().split(",");

            String no = parts.length > 0 ? parts[0].trim() : "";
            String street = parts.length > 1 ? parts[1].trim() : "";
            String city = parts.length > 2 ? parts[2].trim() : "";



            // UPDATE tech_officer
            String sql1 = """
                UPDATE tech_officer 
                SET Name=?, No=?, Street=?, City=? 
                WHERE Techoff_id=?
            """;

            PreparedStatement pst1 = con.prepareStatement(sql1);
            pst1.setString(1, name);
            pst1.setString(2, no);
            pst1.setString(3, street);
            pst1.setString(4, city);
            pst1.setString(5, techOffId);
            pst1.executeUpdate();


            // UPDATE user table
            String sql2 = """
                UPDATE user 
                SET password=?, profile_pic=? 
                WHERE user_id=?
            """;

            PreparedStatement pst2 = con.prepareStatement(sql2);
            pst2.setString(1, password);
            pst2.setString(2, imagePath);
            pst2.setString(3, techOffId);
            pst2.executeUpdate();

            JOptionPane.showMessageDialog(this, "Profile Updated Successfully!");

        } catch (Exception e) {
            e.printStackTrace();
            JOptionPane.showMessageDialog(this, "Error updating profile!");
        }
    }
}

package gui;

import db.DBConnection;

import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

public class TimetableView extends JFrame {
    private JPanel mainPanel;
    private JPanel titlePanel;
    private JScrollPane scrollPanel;
    private JTable table;
    private String role;

    private String techOffId;

    // Admin - with edit button
    public TimetableView(String role){
        this.role = role;
        init();
    }

    // Lecturer/Student/T.O. - No edit button for viewers
    public TimetableView() {
        this.techOffId=techOffId;
        this.role = "Viewer";
        init();
        setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE);

        loadtimetable();
        addWindowListener(new java.awt.event.WindowAdapter() {
            @Override
            public void windowClosed(java.awt.event.WindowEvent e) {
                new TechOfficerDashboard(techOffId).setVisible(true);
            }
        });
    }

    private void init(){
        setContentPane(mainPanel);
        setTitle("View Timetable");
        setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE);
        setSize(1200,600);
        setLocationRelativeTo(null);
        loadtimetable();
    }

    void loadtimetable(){
        String cols[];
        if (role.equals("Admin")){
            cols = new String[]{"ID", "Day", "Start", "End", "Course Code", "Type", "Action"};
        }
        else{
            cols = new String[]{"ID", "Day", "Start", "End", "Course Code", "Type"};
        }
        DefaultTableModel model = new DefaultTableModel(cols,0);

        try (Connection con = DBConnection.getConnection();){
            String query = "SELECT * FROM timetable ORDER BY FIELD(Day, 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'), Start_time";
            PreparedStatement ps = con.prepareStatement(query);
            ResultSet rs = ps.executeQuery();
            while(rs.next()){
                if(role.equals("Admin")){
                    Object[] row={
                            rs.getString("Timetable_id"),
                            rs.getString("Day"),
                            rs.getTime("Start_time"),
                            rs.getTime("End_time"),
                            rs.getString("C_code"),
                            rs.getString("Type"),
                            "Edit"
                    };
                    model.addRow(row);
                }
                else{
                    Object[] row={
                            rs.getString("Timetable_id"),
                            rs.getString("Day"),
                            rs.getTime("Start_time"),
                            rs.getTime("End_time"),
                            rs.getString("C_code"),
                            rs.getString("Type")
                    };
                    model.addRow(row);
                }
            }
            table.setModel(model);
            table.getTableHeader().setBackground(Color.decode("#291c0e"));
            table.getTableHeader().setForeground(Color.WHITE);
            table.getTableHeader().setFont(new Font("Arial", Font.BOLD, 13));
            table.getTableHeader().setPreferredSize(new Dimension(0, 35));
            table.setRowHeight(30);

            // only show EDIT button to admin
            if(role.equals("Admin")) {
                table.getColumn("Action").setCellRenderer((table, value, isSelected, hasFocus, row, column) -> {
                    JButton btn = new JButton("️   Edit");
                    btn.setBackground(Color.decode("#E1D4C2"));
                    btn.setForeground(Color.decode("#291c0e"));
                    return btn;
                });

                table.getColumn("Action").setCellEditor(new DefaultCellEditor(new JCheckBox()){
                    private JButton btn = new JButton("️   Edit");
                    {
                        btn.addActionListener(e -> {
                            int row = table.getSelectedRow();
                            fireEditingStopped();

                            int id = Integer.parseInt(table.getValueAt(row, 0).toString());
                            String day = table.getValueAt(row, 1).toString();
                            String start = table.getValueAt(row, 2).toString();
                            String end = table.getValueAt(row, 3).toString();
                            String code = table.getValueAt(row, 4).toString();
                            String type = table.getValueAt(row, 5).toString();

                            new TimetableEdit(id, day, start, end, code, type, TimetableView.this).setVisible(true);
                            // Parent is passed with the constructor to identify the parent, so it can be refreshed.
                        });
                    }
                    public Component getTableCellEditorComponent(JTable table, Object value, boolean isSelected, int row, int column) {
                        return btn;
                    }
                });

            }

        } catch (SQLException e) {
            e.printStackTrace();
            JOptionPane.showMessageDialog(null, "Error loading Timetable!", "Error",JOptionPane.ERROR_MESSAGE);
        }
    }


}

